utilityBlocks.source:
@utility prose {
    & p {
        margin-top: 1rem;
        margin-bottom: 1rem;
    }
    & p:first-child {
        margin-top: 0;
    }
    & p:last-child {
        margin-bottom: 0;
    }

    & h1,
    & h2,
    & h3,
    & h4,
    & h5,
    & h6 {
        margin-top: 1.5rem;
        margin-bottom: 0.5rem;
    }

    & ul,
    & ol {
        margin-top: 1rem;
        margin-bottom: 1rem;
        padding-left: 1.5rem;
    }

    & li {
        margin-top: 0.25rem;
        margin-bottom: 0.25rem;
    }

    & hr {
        margin-top: 1.75rem;
        margin-bottom: 1.75rem;
        border-color: var(--border--0);
        border-top-width: 1px;
        border-bottom-width: 0;
    }
}

@utility scrollbar-hide {
    -ms-overflow-style: none;
    scrollbar-width: none;
    &::-webkit-scrollbar {
        display: none;
    }
}

@utility slide-in-from-top-* {
    --enter-translate-y: calc(--value(integer) * var(--spacing) * -1);
    --enter-translate-y: calc(--value(--percentage-*, --percentage-translate-*) * -100%);
    --enter-translate-y: calc(--value(ratio) * -100%);
    --enter-translate-y: calc(--value(--translate-*, [percentage], [length]) * -1);
}

