@utility animate-in-centered {
    translate: -50% -50%;
    animation: enter-centered 200ms ease-out both;
}

@utility animate-out-centered {
    translate: -50% -50%;
    animation: exit-centered 200ms ease-in both;
}

@utility markdown-content {
    & p {
        margin: 1.25em 0;
    }

    & p:first-of-type {
        margin-top: 0;
    }

    & p:last-child {
        margin-bottom: 0;
    }

    & code {
        background: rgb(24 24 27);
        padding: 0.125rem 0.25rem;
        border-radius: 0.25rem;
    }

    & pre {
        background: rgb(24 24 27);
        border: 1px solid rgb(63 63 70);
        padding: 0.75rem;
        border-radius: 0.5rem;
        overflow-x: auto;
    }

    & em {
        font-style: italic;
    }

    & strong {
        font-weight: 600;
    }
}

@utility typing-dots {
    display: flex;
    gap: 4px;
    padding: 4px 0;

    & span {
        width: 8px;
        height: 8px;
        background: rgb(167 139 250);
        border-radius: 50%;
        animation: bounce 1.4s infinite ease-in-out both;
    }

    & span:nth-child(1) {
        animation-delay: -0.32s;
    }

    & span:nth-child(2) {
        animation-delay: -0.16s;
    }

    & span:nth-child(3) {
        animation-delay: 0s;
    }
}
